  const link=(s,u,t)=>`#subject/${s.id}/${u.id}/${t?.id||u.topics[0]?.id||''}`;
  const lessonKey=(s,u,t)=>`${s.id}/${u.id}/${t.id}`;
  function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true;}catch{storageOK=false;toast('Browser storage is unavailable or full. Export a backup from Profile.');return false;}}
  function session(){try{user?sessionStorage.setItem('compass-session',user.id):sessionStorage.removeItem('compass-session');}catch{}}
  function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
  function recordActivity(){const day=C.localDay();if(!user.activity.includes(day)){user.activity.push(day);save();}}
  function openModal(title,body){modalOrigin=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;$('#modal').showModal();}
  function closeModal(){if($('#modal').open)$('#modal').close();}
